import { NATIVE_CAPABILITIES } from "../../core/engine.js";
import type { EngineContext, PlayerEngine } from "../../core/engine.js";
import { createPlayerError } from "../../core/errors.js";
import {
  bindMediaElement,
  bufferedEnd,
  safeDuration,
  waitForMetadata,
} from "../../core/media-events.js";
import type { AudioTrackInfo, QualityLevel, TextTrackInfo } from "../../core/types.js";
import { clamp } from "../../core/utils.js";
import { createMediaElement, removeElement } from "../shared/dom.js";
import {
  applyCaptionTracks,
  listAudioTracks,
  listTextTracks,
  setMediaAudioTrack,
  setMediaTextTrack,
} from "../shared/media-tracks.js";

interface HlsLevel {
  readonly height?: number;
  readonly width?: number;
  readonly bitrate?: number;
}

interface HlsInstance {
  readonly levels: readonly HlsLevel[];
  currentLevel: number;
  readonly autoLevelEnabled: boolean;
  attachMedia(media: HTMLMediaElement): void;
  loadSource(url: string): void;
  on(event: string, listener: (...args: unknown[]) => void): void;
  destroy(): void;
}

interface HlsConstructor {
  new (config?: Readonly<Record<string, unknown>>): HlsInstance;
  isSupported(): boolean;
  readonly Events: {
    readonly MANIFEST_PARSED: string;
    readonly LEVEL_SWITCHED: string;
    readonly ERROR: string;
  };
}

interface HlsModule {
  readonly default: HlsConstructor;
}

function toQualities(levels: readonly HlsLevel[]): readonly QualityLevel[] {
  return levels.map((level, index) => {
    const label = level.height === undefined ? `Level ${index + 1}` : `${level.height}p`;

    return {
      id: String(index),
      label,
      ...(level.width === undefined ? {} : { width: level.width }),
      ...(level.height === undefined ? {} : { height: level.height }),
      ...(level.bitrate === undefined ? {} : { bitrate: level.bitrate }),
    };
  });
}

/** HLS engine backed by the optional `hls.js` peer dependency. */
export function createHlsEngine(context: EngineContext): PlayerEngine {
  const { source, options, emit } = context;
  let video: HTMLVideoElement | null = null;
  let hls: HlsInstance | null = null;
  let detach: (() => void) | null = null;
  let qualities: readonly QualityLevel[] = options.qualities ?? [];

  return {
    kind: "video",
    get element() {
      return video;
    },
    capabilities: { ...NATIVE_CAPABILITIES, quality: true },

    async load(): Promise<void> {
      const element = createMediaElement("video", options);
      video = element;
      detach = bindMediaElement(element, emit);
      applyCaptionTracks(element, options.captions?.tracks ?? source.source.captions);
      context.host.append(element);

      const module = (await import("hls.js")) as unknown as HlsModule;
      const Hls = module.default;

      if (!Hls.isSupported()) {
        if (element.canPlayType("application/vnd.apple.mpegurl") === "") {
          throw createPlayerError("HLS playback is not supported in this browser.", {
            code: "unsupported-environment",
          });
        }

        element.src = source.url;
        const metadata = waitForMetadata(element);
        element.load();
        await metadata;
        return;
      }

      const instance = new Hls({
        enableWorker: true,
        lowLatencyMode: options.live ?? false,
        backBufferLength: 90,
      });
      hls = instance;

      await new Promise<void>((resolve, reject) => {
        instance.on(Hls.Events.MANIFEST_PARSED, () => {
          qualities = toQualities(instance.levels);
          resolve();
        });
        instance.on(Hls.Events.ERROR, (...args: unknown[]) => {
          const payload = args[1] as
            | { readonly fatal?: boolean; readonly details?: string }
            | undefined;

          if (payload?.fatal === true) {
            reject(
              createPlayerError("The HLS stream could not be loaded.", {
                code: "network-error",
                details: {
                  ...(payload.details === undefined ? {} : { details: payload.details }),
                  source: source.url,
                },
              }),
            );
          }
        });
        instance.loadSource(source.url);
        instance.attachMedia(element);
      });

      instance.on(Hls.Events.LEVEL_SWITCHED, () => {
        emit("qualitychange", {
          quality: instance.autoLevelEnabled ? null : String(instance.currentLevel),
        });
      });

      await waitForMetadata(element);
    },

    async play(): Promise<void> {
      if (video === null) {
        throw createPlayerError("No media element is attached.", { code: "invalid-state" });
      }

      await video.play();
    },

    pause(): void {
      video?.pause();
    },

    seek(time: number): void {
      if (video !== null) {
        const duration = safeDuration(video);
        video.currentTime = duration > 0 ? clamp(time, 0, duration) : Math.max(0, time);
      }
    },

    setVolume(volume: number): void {
      if (video !== null) {
        video.volume = clamp(volume, 0, 1);
      }
    },

    setMuted(muted: boolean): void {
      if (video !== null) {
        video.muted = muted;
      }
    },

    setPlaybackRate(rate: number): void {
      if (video !== null) {
        video.playbackRate = clamp(rate, 0.25, 4);
      }
    },

    setQuality(quality: string | null): void {
      if (hls !== null) {
        hls.currentLevel = quality === null ? -1 : Number(quality);
      }
    },

    setTextTrack(id: string | null): void {
      if (video !== null) {
        setMediaTextTrack(video, id);
      }
    },

    setAudioTrack(id: string | null): void {
      if (video !== null) {
        setMediaAudioTrack(video, id);
      }
    },

    getQualities(): readonly QualityLevel[] {
      return qualities;
    },

    getTextTracks(): readonly TextTrackInfo[] {
      return video === null ? [] : listTextTracks(video);
    },

    getAudioTracks(): readonly AudioTrackInfo[] {
      return video === null ? [] : listAudioTracks(video);
    },

    getCurrentTime(): number {
      return video?.currentTime ?? 0;
    },

    getDuration(): number {
      return video === null ? 0 : safeDuration(video);
    },

    getBuffered(): number {
      return video === null ? 0 : bufferedEnd(video);
    },

    destroy(): void {
      detach?.();
      detach = null;
      hls?.destroy();
      hls = null;

      if (video !== null) {
        video.pause();
        video.removeAttribute("src");
        video.load();
        removeElement(video);
        video = null;
      }
    },
  };
}
